Input: {"question": "Which line is Belorussky a station on?", "original_source_segments": {"D1S1": {"document_number": 1, "doc_id": "ramdocs-0152-4e06cdf33114:d00", "start": 0, "end": 98, "text": "Belorusskaya (Koltsevaya line) Belorusskaya () is a station on the Moscow Metro's Koltsevaya line."}, "D1S2": {"document_number": 1, "doc_id": "ramdocs-0152-4e06cdf33114:d00", "start": 99, "end": 153, "text": "It is named after the nearby Belorussky Rail Terminal."}, "D1S3": {"document_number": 1, "doc_id": "ramdocs-0152-4e06cdf33114:d00", "start": 154, "end": 257, "text": "It opened in 1952, serving briefly as the terminus of the line before the circle was completed in 1954."}, "D1S4": {"document_number": 1, "doc_id": "ramdocs-0152-4e06cdf33114:d00", "start": 258, "end": 286, "text": "Designed by Ivan Taranov, Z."}, "D1S5": {"document_number": 1, "doc_id": "ramdocs-0152-4e06cdf33114:d00", "start": 287, "end": 299, "text": "Abramova, A."}, "D1S6": {"document_number": 1, "doc_id": "ramdocs-0152-4e06cdf33114:d00", "start": 300, "end": 316, "text": "Markova, and Ya."}, "D1S7": {"document_number": 1, "doc_id": "ramdocs-0152-4e06cdf33114:d00", "start": 317, "end": 532, "text": "Tatarzhinskaya, the station has low, white marble pylons, an elaborately patterned plaster ceiling, light fixtures supported by ornate scroll-shaped brackets, and a variety of decorations based on Belarusian themes."}, "D1S8": {"document_number": 1, "doc_id": "ramdocs-0152-4e06cdf33114:d00", "start": 533, "end": 573, "text": "Overhead, twelve octagonal mosaics by G."}, "D1S9": {"document_number": 1, "doc_id": "ramdocs-0152-4e06cdf33114:d00", "start": 574, "end": 586, "text": "Opryshko, S."}, "D1S10": {"document_number": 1, "doc_id": "ramdocs-0152-4e06cdf33114:d00", "start": 587, "end": 601, "text": "Volkov, and I."}, "D1S11": {"document_number": 1, "doc_id": "ramdocs-0152-4e06cdf33114:d00", "start": 602, "end": 657, "text": "Morozov depict Belarusian daily life, and underfoot the"}, "D2S1": {"document_nu